function escapeName(name: string, charsToEscape: Set<number>): string {
    let lastIndex = 0;
    let escapedName = "";

    for (let index = 0; index < name.length; index++) {
        const charCode = name.charCodeAt(index);
        let shouldEscape = false;
        let replacement = "";

        if (charCode === 0) {
            // Null character -> replacement character
            shouldEscape = true;
            replacement = name.slice(lastIndex, index) + "\\fffd ";
            lastIndex = index + 1;
        } else if (charCode >= 0x01 && charCode <= 0x1f) {
            // Control characters
            shouldEscape = true;
            replacement =
                name.slice(lastIndex, index) +
                "\\" +
                charCode.toString(16) +
                " ";
            lastIndex = index + 1;
        } else if (charCode === 0x7f) {
            // DEL character
            shouldEscape = true;
            replacement = name.slice(lastIndex, index) + "\\7f ";
            lastIndex = index + 1;
        } else if (index === 0 && charCode >= 0x30 && charCode <= 0x39) {
            // Leading digit
            shouldEscape = true;
            replacement = "\\" + charCode.toString(16) + " ";
            lastIndex = index + 1;
        } else if (
            index === 0 &&
            charCode === 0x2d &&
            name.length === 1
        ) {
            // Lone hyphen at the start (entire string is just "-")
            shouldEscape = true;
            replacement = "\\2d ";
            lastIndex = index + 1;
        } else if (
            index === 0 &&
            charCode === 0x2d &&
            name.length > 1 &&
            name.charCodeAt(1) >= 0x30 &&
            name.charCodeAt(1) <= 0x39
        ) {
            // Leading hyphen followed by digit: escape the digit
            escapedName += "-";
            const nextCharCode = name.charCodeAt(1);
            escapedName += "\\" + nextCharCode.toString(16) + " ";
            lastIndex = 2;
            index = 1; // Skip the next iteration
            continue;
        } else if (charsToEscape.has(charCode)) {
            // Regular character escaping
            shouldEscape = true;
            replacement = `${name.slice(lastIndex, index)}\\${name.charAt(index)}`;
            lastIndex = index + 1;
        }

        if (shouldEscape) {
            escapedName += replacement;
        }
    }

    return escapedName.length > 0 ? escapedName + name.slice(lastIndex) : name;
}

