import { AttributeAction, type Selector, SelectorType } from "./types.js";

const attribValueChars = ["\\", '"'];
const pseudoValueChars = [...attribValueChars, "(", ")"];

const charsToEscapeInAttributeValue = new Set(
    attribValueChars.map((c) => c.charCodeAt(0)),
);
const charsToEscapeInPseudoValue = new Set(
    pseudoValueChars.map((c) => c.charCodeAt(0)),
);
const charsToEscapeInName = new Set(
    [
        ...pseudoValueChars,
        "~",
        "^",
        "$",
        "*",
        "+",
        "!",
        "|",
        ":",
        "[",
        "]",
        " ",
        ".",
        "%",
        "#",
        ">",
        "<",
        "/",
        ",",
        ";",
        "'",
    ].map((c) => c.charCodeAt(0)),
);

/**
 * Turns `selector` back into a string.
 * @param selector Selector to stringify.
 */
export function stringify(selector: Selector[][]): string {
    return selector
        .map((token) =>
            token
                .map((token, index, array) =>
                    stringifyToken(token, index, array),
                )
                .join(""),
        )
        .join(", ");
}

function stringifyToken(
    token: Selector,
    index: number,
    array: Selector[],
): string {
    switch (token.type) {
        // Simple types
        case SelectorType.Child: {
            return index === 0 ? "> " : " > ";
        }
        case SelectorType.Parent: {
            return index === 0 ? "< " : " < ";
        }
        case SelectorType.Sibling: {
            return index === 0 ? "~ " : " ~ ";
        }
        case SelectorType.Adjacent: {
            return index === 0 ? "+ " : " + ";
        }
        case SelectorType.Descendant: {
            return " ";
        }
        case SelectorType.ColumnCombinator: {
            return index === 0 ? "|| " : " || ";
        }
        case SelectorType.Universal: {
            // Return an empty string if the selector isn't needed.
            return token.namespace === "*" &&
                index + 1 < array.length &&
                "name" in array[index + 1]
                ? ""
                : `${getNamespace(token.namespace)}*`;
        }

        case SelectorType.Tag: {
            return getNamespacedName(token);
        }

        case SelectorType.PseudoElement: {
            return `::${escapeName(token.name, charsToEscapeInName)}${
                token.data === null
                    ? ""
                    : `(${escapeName(token.data, charsToEscapeInPseudoValue)})`
            }`;
        }

        case SelectorType.Pseudo: {
            return `:${escapeName(token.name, charsToEscapeInName)}${
                token.data === null
                    ? ""
                    : `(${
                          typeof token.data === "string"
                              ? escapeName(
                                    token.data,
                                    charsToEscapeInPseudoValue,
                                )
                              : stringify(token.data)
                      })`
            }`;
        }

        case SelectorType.Attribute: {
            if (
                token.name === "id" &&
                token.action === AttributeAction.Equals &&
                token.ignoreCase === "quirks" &&
                !token.namespace
            ) {
                return `#${escapeName(token.value, charsToEscapeInName)}`;
            }
            if (
                token.name === "class" &&
                token.action === AttributeAction.Element &&
                token.ignoreCase === "quirks" &&
                !token.namespace
            ) {
                return `.${escapeName(token.value, charsToEscapeInName)}`;
            }

            const name = getNamespacedName(token);

            if (token.action === AttributeAction.Exists) {
                return `[${name}]`;
            }

            return `[${name}${getActionValue(token.action)}="${escapeName(
                token.value,
                charsToEscapeInAttributeValue,
            )}"${
                token.ignoreCase === null ? "" : token.ignoreCase ? " i" : " s"
            }]`;
        }
    }
}

function getActionValue(
    action: Exclude<AttributeAction, AttributeAction.Exists>,
): string {
    switch (action) {
        case AttributeAction.Equals: {
            return "";
        }
        case AttributeAction.Element: {
            return "~";
        }
        case AttributeAction.Start: {
            return "^";
        }
        case AttributeAction.End: {
            return "$";
        }
        case AttributeAction.Any: {
            return "*";
        }
        case AttributeAction.Not: {
            return "!";
        }
        case AttributeAction.Hyphen: {
            return "|";
        }
        default: {
            throw new Error("Shouldn't be here");
        }
    }
}

function getNamespacedName(token: {
    name: string;
    namespace: string | null;
}): string {
    return `${getNamespace(token.namespace)}${escapeName(
        token.name,
        charsToEscapeInName,
    )}`;
}

function getNamespace(namespace: string | null): string {
    return namespace === null
        ? ""
        : `${
              namespace === "*"
                  ? "*"
                  : escapeName(namespace, charsToEscapeInName)
          }|`;
}

function escapeName(name: string, charsToEscape: Set<number>): string {
    let lastIndex = 0;
    let escapedName = "";

    for (let index = 0; index < name.length; index++) {
        const charCode = name.charCodeAt(index);
        let shouldEscape = false;
        let replacement = "";

        if (charCode === 0) {
            // Null character -> replacement character
            shouldEscape = true;
            replacement = name.slice(lastIndex, index) + "\\fffd ";
            lastIndex = index + 1;
        } else if (charCode >= 0x01 && charCode <= 0x1f) {
            // Control characters
            shouldEscape = true;
            replacement =
                name.slice(lastIndex, index) +
                "\\" +
                charCode.toString(16) +
                " ";
            lastIndex = index + 1;
        } else if (charCode === 0x7f) {
            // DEL character
            shouldEscape = true;
            replacement = name.slice(lastIndex, index) + "\\7f ";
            lastIndex = index + 1;
        } else if (index === 0 && charCode >= 0x30 && charCode <= 0x39) {
            // Leading digit
            shouldEscape = true;
            replacement = "\\" + charCode.toString(16) + " ";
            lastIndex = index + 1;
        } else if (
            index === 0 &&
            charCode === 0x2d &&
            name.length === 1
        ) {
            // Lone hyphen at the start (entire string is just "-")
            shouldEscape = true;
            replacement = "\\2d ";
            lastIndex = index + 1;
        } else if (
            index === 0 &&
            charCode === 0x2d &&
            name.length > 1 &&
            name.charCodeAt(1) >= 0x30 &&
            name.charCodeAt(1) <= 0x39
        ) {
            // Leading hyphen followed by digit: escape the digit
            escapedName += "-";
            const nextCharCode = name.charCodeAt(1);
            escapedName += "\\" + nextCharCode.toString(16) + " ";
            lastIndex = 2;
            index = 1; // Skip the next iteration
            continue;
        } else if (charsToEscape.has(charCode)) {
            // Regular character escaping
            shouldEscape = true;
            replacement = `${name.slice(lastIndex, index)}\\${name.charAt(index)}`;
            lastIndex = index + 1;
        }

        if (shouldEscape) {
            escapedName += replacement;
        }
    }

    return escapedName.length > 0 ? escapedName + name.slice(lastIndex) : name;
}

